cat > $S/mutate.mjs <<'EOF'
// Mutation testing: break production code in small, meaning-preserving-looking ways
// and see which breakages the suite fails to notice. A SURVIVING mutant is a
// property nothing asserts.
import { readFileSync, writeFileSync } from 'node:fs';
import { execSync, execFileSync } from 'node:child_process';
import { relative, resolve, dirname } from 'node:path';
const R = '/home/user/Claudinite/';

// --- operators, each keyed to a CORRECT/BICEP category -------------------
const OPS = [
  { cat: 'Range',       find: /([^<>=!])>=/g,        make: (m, a) => `${a}>` },
  { cat: 'Range',       find: /([^<>=!])<=/g,        make: (m, a) => `${a}<` },
  { cat: 'Range',       find: /([^<>=!])>([^=])/g,   make: (m, a, b) => `${a}>=${b}` },
  { cat: 'Range',       find: /([^<>=!])<([^=])/g,   make: (m, a, b) => `${a}<=${b}` },
  { cat: 'Conformance', find: /&&/g,                 make: () => '||' },
  { cat: 'Conformance', find: /\|\|/g,               make: () => '&&' },
  { cat: 'Existence',   find: /\?\?/g,               make: () => '||' },
  { cat: 'Conformance', find: /\/\^/g,               make: () => '/' },        // drop a regex start anchor
  { cat: 'Conformance', find: /\$\//g,               make: () => '/' },        // drop a regex end anchor
  { cat: 'Cardinality', find: /\.length === 0/g,     make: () => '.length < 0' },
];

const testsImporting = (mod) => {
  const out = [];
  for (const t of execSync("git ls-files '*.test.mjs'", { cwd: R }).toString().trim().split('\n')) {
    const src = readFileSync(R + t, 'utf8');
    for (const m of src.matchAll(/from\s*['"](\.[^'"]+\.mjs)['"]/g)) {
      if (relative(R, resolve(R, dirname(t), m[1])) === mod) { out.push(t); break; }
    }
  }
  return out;
};

const targets = process.argv.slice(2);
for (const mod of targets) {
  const tests = testsImporting(mod);
  if (!tests.length) { console.log(`SKIP ${mod} — no test imports it`); continue; }
  const original = readFileSync(R + mod, 'utf8');
  const lines = original.split('\n');
  let killed = 0, survived = 0;
  const survivors = [];
  for (let i = 0; i < lines.length; i++) {
    const L = lines[i];
    if (/^\s*(\/\/|\*|\/\*)/.test(L) || !L.trim()) continue;
    for (const op of OPS) {
      op.find.lastIndex = 0;
      if (!op.find.test(L)) continue;
      op.find.lastIndex = 0;
      const mutatedLine = L.replace(op.find, op.make);
      if (mutatedLine === L) continue;
      const mutated = [...lines]; mutated[i] = mutatedLine;
      writeFileSync(R + mod, mutated.join('\n'));
      let ok = false;
      try { execFileSync('node', ['--test', ...tests], { cwd: R, stdio: 'pipe', timeout: 120000 }); ok = true; } catch { ok = false; }
      if (ok) { survived++; survivors.push({ line: i + 1, cat: op.cat, was: L.trim().slice(0, 100), now: mutatedLine.trim().slice(0, 100) }); }
      else killed++;
      writeFileSync(R + mod, original);
      break; // one mutant per line keeps the run bounded
    }
  }
  writeFileSync(R + mod, original);
  console.log(`\n=== ${mod}  (${tests.length} test files)  killed=${killed} survived=${survived}`);
  for (const s of survivors) console.log(`  SURVIVED L${s.line} [${s.cat}]\n      was: ${s.was}\n      now: ${s.now}`);
}
EOF
echo built

