// Right-BICEP's E: every rejection a validator PROMISES is a `bad(...)` call.
// Which of them does a test actually force to happen?
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
const R = '/home/user/Claudinite/';
const mod = process.argv[2];
const src = readFileSync(R + mod, 'utf8');
const tests = execSync("git ls-files '*.test.mjs'", { cwd: R }).toString().trim().split('\n')
  .map((t) => readFileSync(R + t, 'utf8')).join('\n');

// A distinctive fragment of each message — enough to find it quoted in a test.
const msgs = [...src.matchAll(/\bbad\(\s*(['"`])((?:\\.|(?!\1).)*)\1/g)].map((m) => m[2]);
let covered = 0; const gaps = [];
for (const raw of msgs) {
  const msg = raw.replace(/\\"/g, '"').replace(/\\'/g, "'");
  // find the longest quoted-token or plain phrase a test would match on
  const key = (msg.match(/"[a-z_]+"/g) || []).concat(msg.split(/[,;—]/).map((s) => s.trim()))
    .sort((a, b) => b.length - a.length)[0] || msg;
  const probe = msg.slice(0, 40);
  if (tests.includes(probe) || tests.includes(msg)) covered++;
  else gaps.push(msg);
}
console.log(`${mod}\n  ${msgs.length} rejection branches, ${covered} with a test quoting the message, ${gaps.length} without:`);
for (const g of gaps) console.log(`    - ${g.slice(0, 95)}`);
EOF
